earn('beg', 'Beg for coins (every 2 min)', 120, 5, 45, { win: ['A kind stranger dropped some coins.', 'Someone felt generous today.'] }, 0.2, 5);
earn('fish', 'Go fishing (every 5 min)', 300, 30, 150, { win: ['You caught a big tilapia 🐟', 'You reeled in a catfish 🐟', 'You found treasure in a net 🎣'] });
earn('hunt', 'Go hunting (every 6 min)', 360, 40, 180, { win: ['You tracked down a rabbit 🐇', 'You bagged a wild boar 🐗'] });
