      const h = head ? head.split(':') : [];
      const t = tail !== undefined && tail ? tail.split(':') : [];
      const fill = s.includes('::') ? new Array(Math.max(0, 8 - h.length - t.length)).fill('0') : [];
      return [...h, ...fill, ...t].map((x) => parseInt(x || '0', 16));
